import {seed,validState,createRequest,act,stats,filterRecords,toCSV,TECHNICIANS,advanceClock} from './model.mjs';
const $=id=>document.getElementById(id), KEY='relay-demo-v1';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=x=>new Intl.DateTimeFormat('en-AU',{timeZone:'Australia/Brisbane',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(x));
let state=seed(),current=null,storageOK=true;
try{const raw=localStorage.getItem(KEY);if(raw){const saved=JSON.parse(raw);if(validState(saved))state=saved;else $('message').textContent='Invalid local sample was replaced with the original fictional data.'}}catch{$('message').textContent='Local data could not be read. A fresh in-memory sample is ready.';storageOK=false}
const role=()=>$('role').value, filtered=()=>filterRecords(state,$('search').value,$('status-filter').value);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true}catch{storageOK=false}updateStorage()}
function updateStorage(){$('storage-note').textContent=storageOK?'Saved on this browser only. No shared database or agency connection.':'Browser storage unavailable. Changes last for this page session only.'}
function announce(text){$('message').textContent=text}
function render(){const counts=stats(state);for(const [key,value] of Object.entries(counts))$('stat-'+key).textContent=value;$('demo-clock').textContent='Demo clock: '+date(state.now)+' AEST';const records=filtered();$('result-count').textContent=`${records.length} of ${state.records.length} requests shown. Measures above use all requests.`;$('queue').innerHTML=records.map(r=>`<tr><td><button data-request="${esc(r.id)}">${esc(r.id)}</button></td><td>${esc(r.title)}<br><span class="small muted">${esc(r.unit)} · ${esc(r.category)}</span></td><td><span class="tag ${r.priority==='P1'?'red':r.priority==='P2'?'amber':'blue'}">${r.priority}</span></td><td><span class="tag ${r.status==='Closed'?'green':''}">${esc(r.status)}</span></td><td>${esc(r.owner)}</td><td>${date(r.dueAt)}<br>${r.status!=='Closed'&&Date.parse(r.dueAt)<Date.parse(state.now)?'<span class="small" style="color:var(--red)">Past target</span>':''}</td></tr>`).join('');$('empty').hidden=records.length!==0;$('export').disabled=records.length===0;$('new-request').disabled=role()==='Technician';$('new-request').title=role()==='Technician'?'Switch to Requester or Coordinator to submit':'';updateStorage()}
function detail(id,open=true){const r=state.records.find(x=>x.id===id);if(!r)return;current=id;$('detail-error').textContent='';$('detail-id').textContent=r.id;$('detail-title').textContent=r.title;$('detail-description').textContent=r.description;$('detail-meta').innerHTML=[['Unit',r.unit],['Priority',r.priority],['Status',r.status],['Owner',r.owner],['Target time',date(r.dueAt)+' AEST'],['Demo role',role()]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('');$('resolution').innerHTML=r.resolution?`<h3>Latest resolution proposal</h3><p>${esc(r.resolution)}</p>`:'';let controls='';
if(r.status==='Submitted'&&role()==='Coordinator')controls=`<label for="technician">Assign a technician</label><select id="technician"><option value="">Choose a technician</option>${TECHNICIANS.map(t=>`<option>${t}</option>`).join('')}</select><div class="actions"><button class="btn" data-action="assign">Assign request</button></div>`;
if(r.status==='Assigned'&&role()==='Technician')controls='<button class="btn" data-action="start">Start work</button>';
if(r.status==='In progress'&&role()==='Technician')controls='<label for="action-note">Resolution evidence (required)</label><textarea id="action-note" rows="3" maxlength="1000" placeholder="What changed and how was service checked?"></textarea><p class="hint">10–1000 characters.</p><div class="actions"><button class="btn" data-action="resolve">Send for confirmation</button></div>';
if(r.status==='Awaiting confirmation'&&role()==='Requester')controls='<label for="action-note">Reason if the fault remains unresolved</label><textarea id="action-note" rows="3" maxlength="1000" placeholder="Required only when rejecting the resolution."></textarea><p class="hint">Rejection reason: 10–1000 characters.</p><div class="actions"><button class="btn" data-action="confirm">Confirm service restored</button><button class="btn secondary" data-action="reject">Reject resolution</button></div>';
if(!controls)controls=`<p class="notice">${r.status==='Closed'?'Service restored and confirmed. This request is closed.':`Next step: ${r.status==='Submitted'?'Coordinator assigns a technician':r.status==='Assigned'?'Technician starts work':r.status==='In progress'?'Technician records a resolution':'Requester confirms or rejects the resolution'}. Close this panel to switch the demo role.`}</p>`;$('detail-actions').innerHTML=controls;$('history').innerHTML=r.events.map(e=>`<li><strong>${esc(e.action)}</strong>${e.note?`<div>${esc(e.note)}</div>`:''}<small>${date(e.at)} AEST · ${esc(e.role)} · ${esc(e.status)}</small></li>`).join('');if(open&&!$('detail-dialog').open)$('detail-dialog').showModal()}
$('new-request').onclick=()=>{$('create-error').textContent='';$('create-dialog').showModal()};
$('create-form').onsubmit=e=>{e.preventDefault();try{const r=createRequest(state,Object.fromEntries(new FormData(e.currentTarget)),role());save();render();$('create-dialog').close();e.currentTarget.reset();announce(`${r.id} submitted. Switch to Coordinator to assign a technician.`);detail(r.id)}catch(err){$('create-error').textContent=err.message}};
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close)$(close.dataset.close).close();const request=e.target.closest('[data-request]');if(request)detail(request.dataset.request);const action=e.target.closest('[data-action]');if(action){try{const r=act(state,current,action.dataset.action,role(),{owner:$('technician')?.value,note:$('action-note')?.value});save();render();detail(r.id,false);announce(`${r.id} updated: ${r.status}.`)}catch(err){$('detail-error').textContent=err.message}}});
$('search').oninput=render;$('status-filter').onchange=render;$('role').onchange=()=>{render();if($('detail-dialog').open)detail(current,false)};
$('export').onclick=()=>{const blob=new Blob(['\ufeff'+toCSV(filtered())],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='relay-fictional-queue.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce(`${filtered().length} fictional requests exported.`)};
$('advance').onclick=()=>{advanceClock(state,24);save();render();announce('Demo clock advanced by 24 hours. Target times were recalculated against the new clock.')};
$('reset').onclick=()=>$('reset-dialog').showModal();$('confirm-reset').onclick=()=>{state=seed();$('search').value='';$('status-filter').value='All';$('role').value='Requester';save();render();$('reset-dialog').close();announce('Eight fictional sample requests restored.')};
render();
const context=document.modelContext,lifecycle=new AbortController();
if(context?.registerTool){try{Promise.resolve(context.registerTool({name:'list_relay_demo_requests',title:'List fictional service requests',description:'Read the same filtered local demo queue shown in the interface. Does not change records.',inputSchema:{type:'object',properties:{query:{type:'string'},status:{type:'string',enum:['All','Submitted','Assigned','In progress','Awaiting confirmation','Closed']}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!['query','status'].includes(k))||('query'in input&&typeof input.query!=='string')||('status'in input&&!['All','Submitted','Assigned','In progress','Awaiting confirmation','Closed'].includes(input.status)))throw new Error('Invalid filters');return filterRecords(state,input.query??'',input.status??'All').map(({id,title,status,priority,owner})=>({id,title,status,priority,owner}))}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
